package com.alsafa.native4.core;

import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import java.util.UUID;
/** Explicit final-price change only. Partial payments must never call this store. */
public final class SettlementAdjustmentStore {
 private SettlementAdjustmentStore(){}
 public static Result requireAndWrite(SQLiteDatabase db,String sourceType,String sourceId,double agreed,double finalAmount,String currency,boolean confirmed,String reason,long now){String cur=MoneyRules.currency(currency);if(!Double.isFinite(agreed)||agreed<0||!Double.isFinite(finalAmount)||finalAmount<0)throw new IllegalArgumentException("المبلغ غير صالح");double delta=finalAmount-agreed;if(Math.abs(delta)<0.000001)return new Result(false,0,0,"NONE",null);String kind=delta<0?"CUSTOMER_DISCOUNT":"PRICE_INCREASE";double discount=delta<0?-delta:0;if(!confirmed)throw new ConfirmationRequiredException(agreed,finalAmount,discount,cur,kind);String id="adjustment-"+UUID.randomUUID();ContentValues v=new ContentValues();v.put("adjustment_id",id);v.put("source_type",sourceType);v.put("source_id",sourceId);v.put("agreed_amount",agreed);v.put("collected_amount",finalAmount);v.put("currency",cur);v.put("difference",delta);v.put("reason",prefix(kind,reason));v.put("created_at",now);db.insertOrThrow("settlement_adjustments",null,v);return new Result(true,delta,discount,kind,id);}
 private static String prefix(String kind,String reason){String r=reason==null?"":reason.trim();String p="CUSTOMER_DISCOUNT".equals(kind)?"CUSTOMER_DISCOUNT":"PRICE_INCREASE";return r.isEmpty()?p:p+": "+r;}
 public static final class ConfirmationRequiredException extends IllegalStateException{public final double agreed,finalAmount,discount;public final String currency,kind;ConfirmationRequiredException(double a,double f,double d,String cur,String k){super(k.equals("CUSTOMER_DISCOUNT")?"القيمة الأصلية "+a+" "+cur+"، والقيمة بعد التعديل "+f+" "+cur+". سيتم تسجيل "+d+" "+cur+" كحسم للعميل. هل تريد المتابعة؟":"القيمة الأصلية "+a+" "+cur+"، والقيمة بعد التعديل "+f+" "+cur+". سيتم تسجيل زيادة "+(f-a)+" "+cur+". هل تريد المتابعة؟");agreed=a;finalAmount=f;discount=d;currency=cur;kind=k;}}
 public static final class Result{public final boolean adjusted;public final double difference,discount;public final String kind,adjustmentId;Result(boolean a,double d,double disc,String k,String id){adjusted=a;difference=d;discount=disc;kind=k;adjustmentId=id;}}
}
